param([Parameter(Mandatory=$true)][ValidateSet('PRECHECK','INSTALL','ARM','RETRIEVE','VERIFY','UNINSTALL','POSTCHECK')][string]$Stage,[Parameter(Mandatory=$true)][string]$SessionDirectory,[string]$ProofDirectory,[string]$Serial,[ValidateSet('','M6_AOA_ONLY_AFTER_REVIEWED_M5_PASS')][string]$LiveAuthorization='',[ValidateSet(10089,10085)][int]$ProductId=10089)
$ErrorActionPreference='Stop';$root=Split-Path (Split-Path $PSScriptRoot -Parent) -Parent;$base="$root/analysis/parallel-aa-receiver";$package='com.rdx.fullscreen.m6aoa';$factory='com.honda.androidauto.projection.sink'
$pre=(& "$PSScriptRoot/Test-M6FrozenPreflight.ps1" -ProofDirectory $ProofDirectory|ConvertFrom-Json)
if($Stage-eq'PRECHECK'){if(Test-Path -LiteralPath $SessionDirectory){throw 'Fresh local preparation directory required'};New-Item -ItemType Directory -Path $SessionDirectory|Out-Null;$SessionDirectory=(Resolve-Path $SessionDirectory).Path;[ordered]@{phase='PREPARED_OFFLINE';runId=('m6_'+[guid]::NewGuid().ToString('N'));apkSHA256=$pre.sha256;M5proofVerified=$pre.reviewedM5Pass;liveExecutionEnabled=$pre.liveExecutionEnabled;liveExecuted=$false;productId=$ProductId;phoneSwap='manual single port';next='M5 RETRY ONLY; no frozen M6 live execution'}|ConvertTo-Json|Set-Content "$SessionDirectory/session.json";Write-Output 'OFFLINE PRECHECK ONLY. M6 LIVE-DISABLED; no ADB invoked.';return}
# Deliberately before process launch or device enumeration. No bypass or activation switch exists.
if(-not$pre.liveExecutionEnabled){throw 'M6 LIVE-DISABLED FROZEN RELEASE. No ADB invoked. A separately reviewed activation release would be required after M5 PASS.'}
if(($Stage-in@('INSTALL','ARM')-and-not$pre.reviewedM5Pass)-or$LiveAuthorization-ne'M6_AOA_ONLY_AFTER_REVIEWED_M5_PASS'-or$Serial-ne'00000000'){throw 'Reviewed signed M5 PASS for INSTALL/ARM, separate M6 authorization and exact recorded serial required; no ADB invoked'}
$SessionDirectory=(Resolve-Path $SessionDirectory).Path;$state=Get-Content "$SessionDirectory/session.json" -Raw|ConvertFrom-Json;if($state.apkSHA256-ne$pre.sha256){throw 'M6 session APK mismatch'};$adb=$pre.adb
function Save{$state|ConvertTo-Json -Depth 6|Set-Content "$SessionDirectory/session.json"}
function Adb([string[]]$Arguments,[string]$InputFile,[string]$OutputFile,[switch]$AllowFailure){
 $psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName=$adb;$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;$psi.RedirectStandardInput=[bool]$InputFile
 foreach($arg in (@('-s',$Serial)+$Arguments)){$psi.ArgumentList.Add($arg)}
 $process=[Diagnostics.Process]::new();$process.StartInfo=$psi;[void]$process.Start();$errors=$process.StandardError.ReadToEndAsync();$output=if($OutputFile){[IO.File]::Create($OutputFile)}else{[IO.MemoryStream]::new()};$copy=$process.StandardOutput.BaseStream.CopyToAsync($output)
 try{if($InputFile){$in=[IO.File]::OpenRead((Resolve-Path $InputFile).Path);try{$task=$in.CopyToAsync($process.StandardInput.BaseStream);if(-not$task.Wait(30000)){$process.Kill();throw 'M6 input transfer bound'}}finally{$in.Dispose();$process.StandardInput.Close()}};if(-not$process.WaitForExit(30000)){$process.Kill();throw 'M6 command bound'};$process.WaitForExit();if(-not$copy.Wait(30000)){throw 'Output drain bound'};$err=$errors.Result;Add-Content "$SessionDirectory/commands.jsonl" ([ordered]@{utc=[DateTime]::UtcNow.ToString('o');serial=$Serial;arguments=$Arguments;exit=$process.ExitCode;stderr=$err}|ConvertTo-Json -Compress);if($process.ExitCode-ne0-and-not$AllowFailure){throw "Future M6 command failed: $($Arguments-join' ')"};if(-not$OutputFile){return [Text.Encoding]::UTF8.GetString($output.ToArray())}}finally{$output.Dispose();$process.Dispose()}
}
$api=(Adb -Arguments @('shell','getprop','ro.build.version.sdk')).Trim();$fp=(Adb -Arguments @('shell','getprop','ro.build.fingerprint')).Trim();if($api-ne'22'-or$fp-ne'Acura/gen1CBD_HS/gen1CBD_HS:5.1.1/LMY48P/14:user/release-keys'){throw 'Runtime/firmware differs; stop and review before device action'}
function Snapshot([string]$Name){$dir=Join-Path $SessionDirectory $Name;New-Item -ItemType Directory -Path $dir|Out-Null;foreach($item in @(@('usb','shell','dumpsys','usb'),@('wm-size','shell','wm','size'),@('display','shell','dumpsys','display'),@('honda-package','shell','dumpsys','package',$factory))){Adb -Arguments $item[1..($item.Length-1)] -OutputFile "$dir/$($item[0]).txt"|Out-Null};$path=(Adb -Arguments @('shell','pm','path',$factory)).Trim();if($path-notmatch'^package:(/system/(app|priv-app)/[A-Za-z0-9_./-]+\.apk)$'){throw 'Factory path changed'};[void](Adb -Arguments @('pull',$Matches[1],"$dir/factory-aa.apk"));if((Get-FileHash "$dir/factory-aa.apk").Hash-ne'F9E976F44853C9DB7C8FF5A8610C10CAF1E0B4D1E5BE0886F4F52505C5348146'){throw 'Factory APK differs; preserve and stop'};& 'C:/Program Files/Eclipse Adoptium/jdk-17.0.20.101-hotspot/bin/java.exe' -jar 'C:/Program Files (x86)/Android/android-sdk/build-tools/32.0.0/lib/apksigner.jar' verify --min-sdk-version 22 --max-sdk-version 22 --print-certs "$dir/factory-aa.apk" *> "$dir/honda-signer.txt";if($LASTEXITCODE-ne0){throw 'Factory signer verification failed'}}
switch($Stage){
 'INSTALL'{if($state.phase-ne'PREPARED_OFFLINE'){throw 'Fresh prepared session required'};if((Adb -Arguments @('shell','pm','list','packages',$package))-match('(?m)^package:'+[regex]::Escape($package)+'\s*$')){throw 'M6 exists; preserve old evidence'};Snapshot before;[void](Adb -Arguments @('install','-t',$pre.apk));[void](Adb -Arguments @('shell','run-as',$package,'mkdir','-p','files/reviewed-m5'));foreach($name in @('proof.m5review','proof.sig','evidence.zip')){[void](Adb -Arguments @('exec-in','run-as',$package,'dd',"of=files/reviewed-m5/$name") -InputFile (Join-Path $ProofDirectory $name))};$installed=Adb -Arguments @('shell','dumpsys','package',$package);$installed|Set-Content "$SessionDirectory/m6-package.txt";if($installed-notmatch'userId=1[0-9]{4}'-or$installed-notmatch'versionName=0\.1\.0-m6-aoa-only-frozen'){throw 'Ordinary installed package/version not verified'};$state.phase='INSTALLED';$state.liveExecuted=$true;Save}
 'ARM'{if($state.phase-ne'INSTALLED'){throw 'Exactly one fresh ARM'};$state.phase='ARM_ATTEMPTED';Save;[void](Adb -Arguments @('shell','am','startservice','-n',"$package/.M6AoaService",'-a','com.rdx.fullscreen.m6aoa.ARM_REVIEWED_M6','--ez','m6_separately_authorized','true','--es','run_id',$state.runId,'--ei','vendor_id','8921','--ei','product_id',[string]$state.productId));$armed=Adb -Arguments @('exec-out','run-as',$package,'cat',"files/runs/$($state.runId)/armed.txt");$armed|Set-Content "$SessionDirectory/armed.txt";if($armed-notmatch('(?m)^run='+[regex]::Escape($state.runId)+'\s*$')-or$armed-notmatch'(?m)^state=WAIT_TARGET\s*$'){throw 'Durable fresh ARM not confirmed; do not swap'};$domain=Adb -Arguments @('shell','ps','-Z');$domain|Set-Content "$SessionDirectory/armed-processes.txt";if(($domain-split'\r?\n'|Where-Object {$_-match'com\.rdx\.fullscreen\.m6aoa\s*$'})-notmatch'u:r:untrusted_app:s0'){throw 'M6 untrusted process not verified; do not swap; retrieve evidence'};$state.phase='PHONE_SWAP_WAIT_RECONNECT';Save;Write-Output 'STOP ADB NOW. Unplug laptop, connect unlocked phone, manually ALLOW own M6 permission dialog if shown. No permanent/default handler. Do not reconnect/loop AOA. After bounded run disconnect phone, reconnect laptop, RETRIEVE.'}
 'RETRIEVE'{if($state.phase-notin@('PHONE_SWAP_WAIT_RECONNECT','ARM_ATTEMPTED')){throw 'Retrieve only armed session'};Adb -Arguments @('logcat','-d','-v','threadtime') -OutputFile "$SessionDirectory/system-logcat.txt"|Out-Null;$missing=@();foreach($name in @('journal.txt','summary.txt')){Adb -Arguments @('exec-out','run-as',$package,'cat',"files/runs/$($state.runId)/$name") -OutputFile "$SessionDirectory/$name" -AllowFailure|Out-Null;if((Get-Item "$SessionDirectory/$name").Length-eq0){$missing+=$name}};if($ProofDirectory){Copy-Item "$ProofDirectory/proof.m5review","$ProofDirectory/proof.sig" $SessionDirectory};[ordered]@{missingOrEmpty=$missing;verdict=if($missing.Count){'INCONCLUSIVE: preserve failure logs; do not rerun START'}else{'REVIEW_REQUIRED'};notM6Pass=$true}|ConvertTo-Json|Set-Content "$SessionDirectory/retrieval-status.json";Get-ChildItem $SessionDirectory -File|Get-FileHash|ConvertTo-Json|Set-Content "$SessionDirectory/evidence-hashes.json";$state.phase='RETRIEVED';Save}
 'VERIFY'{if($state.phase-ne'RETRIEVED'){throw 'Retrieve first'};& "$PSScriptRoot/Test-M6Evidence.ps1" -Journal "$SessionDirectory/journal.txt" -Summary "$SessionDirectory/summary.txt" -Output "$SessionDirectory/verdict.json";$state.phase='VERIFIED';Save;Write-Output 'Manual evidence and causation review required. STOP; M7 not authorized.'}
 'UNINSTALL'{if($state.phase-notin@('RETRIEVED','VERIFIED')){throw 'Evidence retrieval before cleanup required'};$result=Adb -Arguments @('uninstall',$package);if($result-notmatch'Success'){throw 'Uninstall unconfirmed'};if((Adb -Arguments @('shell','pm','list','packages',$package))-match('(?m)^package:'+[regex]::Escape($package)+'\s*$')-or(Adb -Arguments @('shell','ps'))-match'com\.rdx\.fullscreen\.m6aoa\s*$'){throw 'Package/process remains'};$state.phase='UNINSTALLED';Save}
 'POSTCHECK'{if($state.phase-ne'UNINSTALLED'){throw 'Uninstall first'};Snapshot after;foreach($file in @('wm-size.txt','honda-signer.txt')){if((Get-Content "$SessionDirectory/before/$file" -Raw)-ne(Get-Content "$SessionDirectory/after/$file" -Raw)){throw 'Factory signer/display preservation mismatch; investigate without modifying Honda'}};[ordered]@{packageAbsent=$true;processAbsent=$true;factoryHashSignerSame=$true;wmSizeSame=$true;privateDataEquality='NOT CLAIMED';normalUninstallDataGuarantee=$true;next='STOP; M7 NOT AUTHORIZED'}|ConvertTo-Json|Set-Content "$SessionDirectory/postcheck.json";$state.phase='FINISHED';Save}
}
